example_request.javascript:
import { readFile, writeFile } from 'node:fs/promises';
const form = new FormData();
form.append("model", "flux2-klein-4b");
form.append("prompt", "A small teal fish mark on a clean white card.");
form.append("size", "64x64");
form.append("extensions", "{\"com.azizam.workflow\":{\"steps\":1,\"guidance\":0.0,\"denoise\":1}}");
form.append("image", new Blob([await readFile("./source-image.png")]), "source-image.png");
form.append("mask", new Blob([await readFile("./mask.png")]), "mask.png");
const response = await fetch("/v1/images/edits", {
  method: "POST",
  headers: { authorization: `Bearer ${process.env.AZIZAM_API_KEY}` },
  body: form
});
if (!response.ok) throw new Error(await response.text());
await writeFile('workflow-output.bin', Buffer.from(await response.arrayBuffer()));

